// word is "SİL" (dotted İ — compared with Turkish case folding, see src/utils/textCase.ts); the partner feature is
// "AWA Birlikte"; language names are endonyms ("Türkçe"). Religious-practice terms follow common Turkish usage
// (namaz, oruç, kaza, nifas/lohusalık, istihaze, gusül) and stay neutral and educational.
